package com.webproject.esoteria.controller;

import com.webproject.esoteria.domain.dto.clientDTO;
import com.webproject.esoteria.service.JwtService;
import com.webproject.esoteria.service.clientService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/clients")
@CrossOrigin(origins = "http://localhost:4200", allowedHeaders = "*", methods = {RequestMethod.GET, RequestMethod.POST, RequestMethod.PUT, RequestMethod.DELETE})
public class ClientController {
    private final JwtService jwtService;
    private final clientService clientService;

    public ClientController(JwtService jwtService, clientService clientService) {
        this.jwtService = jwtService;
        this.clientService = clientService;
    }

    @GetMapping
    public ResponseEntity<List<clientDTO>> listClients(
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        return ResponseEntity.ok(clientService.listAll());
    }

    @GetMapping("/{id}")
    public ResponseEntity<clientDTO> getClientById(
            @PathVariable Long id,
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        clientDTO client = clientService.getById(id);
        return client != null ? ResponseEntity.ok(client) : ResponseEntity.notFound().build();
    }

    @PostMapping
    public ResponseEntity<clientDTO> createClient(
            @Valid @RequestBody clientDTO request
    ) {

        return ResponseEntity.status(HttpStatus.CREATED).body(clientService.create(request));
    }

    @PutMapping("/{id}")
    public ResponseEntity<clientDTO> updateClient(
            @PathVariable Long id,
            @Valid @RequestBody clientDTO request,
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        clientDTO updatedClient = clientService.update(id, request);
        return updatedClient != null ? ResponseEntity.ok(updatedClient) : ResponseEntity.notFound().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteClient(
            @PathVariable Long id,
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        clientDTO deletedClient = clientService.delete(id);
        return deletedClient != null ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();
    }

    private HttpStatus resolveAdminAccessError(String authorization) {
        if (!jwtService.isValidAuthorizationHeader(authorization)) {
            return HttpStatus.UNAUTHORIZED;
        }

        return jwtService.isValidAdminAuthorizationHeader(authorization) ? null : HttpStatus.FORBIDDEN;
    }
}

package com.webproject.esoteria.controller;

import com.webproject.esoteria.domain.dto.clientDTO;
import com.webproject.esoteria.service.JwtService;
import com.webproject.esoteria.service.clientService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/clients")
@CrossOrigin(origins = "http://localhost:4200", allowedHeaders = "*", methods = {RequestMethod.GET, RequestMethod.POST, RequestMethod.PUT, RequestMethod.DELETE})
public class ClientController {
    private final JwtService jwtService;
    private final clientService clientService;

    public ClientController(JwtService jwtService, clientService clientService) {
        this.jwtService = jwtService;
        this.clientService = clientService;
    }

    @GetMapping
    public ResponseEntity<List<clientDTO>> listClients() {
        return ResponseEntity.ok(clientService.listAll());
    }

    @GetMapping("/{id}")
    public ResponseEntity<clientDTO> getClientById(@PathVariable Long id) {
        clientDTO client = clientService.getById(id);
        return client != null ? ResponseEntity.ok(client) : ResponseEntity.notFound().build();
    }

    @PostMapping
    public ResponseEntity<clientDTO> createClient(
            @Valid @RequestBody clientDTO request
    ) {

        return ResponseEntity.status(HttpStatus.CREATED).body(clientService.create(request));
    }

    @PutMapping("/{id}")
    public ResponseEntity<clientDTO> updateClient(
            @PathVariable Long id,
            @Valid @RequestBody clientDTO request,
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        clientDTO updatedClient = clientService.update(id, request);
        return updatedClient != null ? ResponseEntity.ok(updatedClient) : ResponseEntity.notFound().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteClient(
            @PathVariable Long id,
            @RequestHeader(value = "Authorization", required = false) String authorization
    ) {
        HttpStatus accessError = resolveAdminAccessError(authorization);
        if (accessError != null) {
            return ResponseEntity.status(accessError).build();
        }

        clientDTO deletedClient = clientService.delete(id);
        return deletedClient != null ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();
    }

    private HttpStatus resolveAdminAccessError(String authorization) {
        if (!jwtService.isValidAuthorizationHeader(authorization)) {
            return HttpStatus.UNAUTHORIZED;
        }

        return jwtService.isValidAdminAuthorizationHeader(authorization) ? null : HttpStatus.FORBIDDEN;
    }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Client {
  id?: number;
  name: string;
  password_hash: string;
  dni: string;
  birthday_date: string;
  create_date?: string;
}

@Injectable({
  providedIn: 'root'
})
export class ClientService {
  private apiUrl = 'http://localhost:8080/api/clients';

  constructor(private http: HttpClient) { }

  listClients(): Observable<Client[]> {
    return this.http.get<Client[]>(this.apiUrl);
  }

  getClientById(id: number): Observable<Client> {
    return this.http.get<Client>(`${this.apiUrl}/${id}`);
  }

  createClient(client: Client): Observable<Client> {
    return this.http.post<Client>(this.apiUrl, client);
  }

  updateClient(id: number, client: Client): Observable<Client> {
    return this.http.put<Client>(`${this.apiUrl}/${id}`, client);
  }

  deleteClient(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface Client {
  id?: number;
  name: string;
  password_hash: string;
  dni: string;
  birthday_date: string;
  create_date?: string;
}

@Injectable({
  providedIn: 'root'
})
export class ClientService {
  private apiUrl = 'http://localhost:8080/api/clients';

  constructor(private http: HttpClient) { }

  listClients(): Observable<Client[]> {
    return this.http.get<any[]>(this.apiUrl).pipe(
      map(data => {
        console.log('Raw data from backend:', data);
        return data.map(client => this.mapClient(client));
      })
    );
  }

  getClientById(id: number): Observable<Client> {
    return this.http.get<any>(`${this.apiUrl}/${id}`).pipe(
      map(client => this.mapClient(client))
    );
  }

  createClient(client: Client): Observable<Client> {
    return this.http.post<any>(this.apiUrl, client).pipe(
      map(resp => this.mapClient(resp))
    );
  }

  updateClient(id: number, client: Client): Observable<Client> {
    return this.http.put<any>(`${this.apiUrl}/${id}`, client).pipe(
      map(resp => this.mapClient(resp))
    );
  }

  deleteClient(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }

  private mapClient(rawData: any): Client {
    console.log('Mapping client:', rawData);
    return {
      id: rawData.id,
      name: rawData.name,
      password_hash: rawData.password_hash,
      dni: rawData.dni,
      birthday_date: typeof rawData.birthday_date === 'string' ? rawData.birthday_date : rawData.birthday_date,
      create_date: typeof rawData.create_date === 'string' ? rawData.create_date : rawData.create_date
    };
  }
}

import { Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { ClientService, Client } from '../../service/client.service';

@Component({
  selector: 'app-clients',
  imports: [CommonModule, FormsModule, ReactiveFormsModule],
  templateUrl: './clients.html',
  styleUrl: './clients.css',
})
export class Clients implements OnInit {
  clients: Client[] = [];
  loading: boolean = false;
  errorMessage: string = '';

  showForm: boolean = false;
  editingId: number | null = null;
  showDeleteConfirm: boolean = false;
  clientToDelete: number | null = null;

  formData: Partial<Client> = {
    name: '',
    password_hash: '',
    dni: '',
    birthday_date: '',
  };

  constructor(private clientService: ClientService, private cdr: ChangeDetectorRef) { }

  ngOnInit(): void {
    this.loadClients();
  }

  loadClients(): void {
    this.loading = true;
    this.errorMessage = '';
    console.log('Iniciando carga de clientes...');
    this.clientService.listClients().subscribe({
      next: (data) => {
        console.log('Datos recibidos:', data);
        console.log('Tipo de data:', typeof data);
        console.log('Es array:', Array.isArray(data));
        this.clients = data;
        this.loading = false;
        console.log('Loading set to false, clients:', this.clients);
      },
      error: (err) => {
        console.error('Error en la llamada:', err);
        console.error('Status:', err.status);
        console.error('Message:', err.message);
        this.errorMessage = 'Error clientes no cargados.';
        this.loading = false;
      }
    });
  }

  openForm(client?: Client): void {
    if (client) {
      this.editingId = client.id || null;
      this.formData = { ...client };
    } else {
      this.editingId = null;
      this.formData = {
        name: '',
        password_hash: '',
        dni: '',
        birthday_date: '',
      };
    }
    this.showForm = true;
  }

  closeForm(): void {
    this.showForm = false;
    this.editingId = null;
    this.formData = {
      name: '',
      password_hash: '',
      dni: '',
      birthday_date: '',
    };
  }

  saveClient(): void {
    if (!this.formData.name || !this.formData.dni || !this.formData.password_hash) {
      this.errorMessage = 'Por favor, completa todos los campos requeridos';
      return;
    }

    this.loading = true;
    const clientToSave = {
      name: this.formData.name!,
      password_hash: this.formData.password_hash!,
      dni: this.formData.dni!,
      birthday_date: this.formData.birthday_date || new Date().toISOString().split('T')[0],
    };

    if (this.editingId) {
      // Actualizar
      this.clientService.updateClient(this.editingId, clientToSave).subscribe({
        next: () => {
          this.loadClients();
          this.closeForm();
          this.errorMessage = '';
        },
        error: (err) => {
          this.errorMessage = 'Error al actualizar el cliente';
          console.error(err);
          this.loading = false;
        }
      });
    } else {
      // Crear
      this.clientService.createClient(clientToSave).subscribe({
        next: () => {
          this.loadClients();
          this.closeForm();
          this.errorMessage = '';
        },
        error: (err) => {
          this.errorMessage = 'Error al crear el cliente';
          console.error(err);
          this.loading = false;
        }
      });
    }
  }

  deleteClient(id: number): void {
    this.clientToDelete = id;
    this.showDeleteConfirm = true;
  }

  confirmDelete(): void {
    if (this.clientToDelete !== null) {
      this.loading = true;
      this.clientService.deleteClient(this.clientToDelete).subscribe({
        next: () => {
          this.loadClients();
          this.cancelDelete();
          this.errorMessage = '';
        },
        error: (err) => {
          this.errorMessage = 'Error al eliminar el cliente';
          console.error(err);
          this.loading = false;
        }
      });
    }
  }

  cancelDelete(): void {
    this.showDeleteConfirm = false;
    this.clientToDelete = null;
  }

  editClient(client: Client): void {
    this.openForm(client);
  }
}

import { Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { ClientService, Client } from '../../service/client.service';

@Component({
